from jsonb_to_recordset($q$[{"id":3039,"materia":"ml","nivel":1,"enunciado":"O ramo da Medicina Legal que estuda as lesões corporais é a:","opcoes":["Traumatologia forense","Tanatologia","Sexologia forense","Psiquiatria forense e criminologia clínica"],"explicacao":"Estuda os agentes e as lesões que produzem."},{"id":3040,"materia":"ml","nivel":1,"enunciado":"O ramo da Medicina Legal que estuda a morte e o cadáver é a:","opcoes":["Tanatologia","Traumatologia","Toxicologia","Infortunística"],"explicacao":"Inclui fenômenos cadavéricos e necropsia."},{"id":3041,"materia":"ml","nivel":2,"enunciado":"A sexologia forense estuda:","opcoes":["Questões médico-legais ligadas à sexualidade, como os crimes sexuais","Apenas doenças venéreas e sua notificação obrigatória","A morte súbita","A identificação por DNA"],"explicacao":"Inclui exames em casos de violência sexual."},{"id":3042,"materia":"ml","nivel":1,"enunciado":"O instrumento contundente produz lesões como:","opcoes":["Equimose, hematoma e escoriação","Ferida incisa","Ferida punctória","Ferida perfuroincisa de bordas regulares"],"explicacao":"Age por pressão, choque ou atrito."},{"id":3043,"materia":"ml","nivel":2,"enunciado":"O hematoma se diferencia da equimose porque:","opcoes":["Forma uma coleção de sangue que eleva a pele","Não contém sangue","Não muda de cor com o passar dos dias","É típico de arma de fogo"],"explicacao":"Na equimose o sangue se infiltra nos tecidos."},{"id":3044,"materia":"ml","nivel":2,"enunciado":"Nas feridas incisas, a cauda de escoriação indica:","opcoes":["O fim do trajeto do instrumento","O início do golpe, onde a lâmina entrou primeiro","Disparo encostado","Mordedura"],"explicacao":"Ajuda a saber a direção do corte."},{"id":3045,"materia":"ml","nivel":1,"enunciado":"Nas feridas incisas, as bordas costumam ser:","opcoes":["Regulares e lisas","Irregulares e escoriadas","Queimadas","Invertidas com tatuagem"],"explicacao":"O instrumento cortante age por deslizamento."},{"id":3046,"materia":"ml","nivel":2,"enunciado":"No tiro a distância, além do alcance dos resíduos, o orifício de entrada apresenta:","opcoes":["Orlas de contusão e enxugo, sem tatuagem","Zona de tatuagem intensa","Câmara de mina","Queimadura com o formato da boca do cano"],"explicacao":"Sem os efeitos secundários do disparo."},{"id":3047,"materia":"ml","nivel":2,"enunciado":"A zona de tatuagem é formada por:","opcoes":["Grãos de pólvora incrustados na pele","Fuligem superficial que sai com simples lavagem","Sangue coagulado","Restos de roupa"],"explicacao":"Não sai com a limpeza."},{"id":3048,"materia":"ml","nivel":2,"enunciado":"A zona de esfumaçamento difere da tatuagem porque:","opcoes":["Sai com a limpeza da pele","Não sai com a lavagem","Só aparece no orifício de saída","Indica tiro de longe"],"explicacao":"É depósito superficial de fuligem."},{"id":3049,"materia":"ml","nivel":1,"enunciado":"A sufocação direta ocorre por:","opcoes":["Obstrução da boca e do nariz ou das vias aéreas","Constrição do pescoço com laço ou com as mãos","Imersão em água","Queda de pressão"],"explicacao":"Ex.: travesseiro sobre o rosto."},{"id":3050,"materia":"ml","nivel":2,"enunciado":"Impedir a respiração comprimindo o tórax, como em soterramento ou multidão, é asfixia por:","opcoes":["Compressão torácica (sufocação indireta)","Enforcamento","Afogamento","Esganadura"],"explicacao":"Restrição aos movimentos do tórax."},{"id":3051,"materia":"ml","nivel":2,"enunciado":"A asfixia por confinamento, em ambiente fechado, é asfixia por:","opcoes":["Modificação do meio ambiente","Constrição cervical","Compressão torácica","Obstrução das vias aéreas por corpo estranho"],"explicacao":"O ar respirável se esgota."},{"id":3052,"materia":"ml","nivel":1,"enunciado":"No afogamento, costuma aparecer na boca e no nariz:","opcoes":["Cogumelo de espuma","Sangue escuro coagulado","Pó branco","Nada"],"explicacao":"Espuma fina e persistente."},{"id":3053,"materia":"ml","nivel":2,"enunciado":"A “pele de lavadeira” em corpo retirado da água indica:","opcoes":["Permanência prolongada em meio líquido","Morte por fogo","Disparo encostado","Envenenamento"],"explicacao":"Enrugamento das mãos e pés."},{"id":3054,"materia":"ml","nivel":1,"enunciado":"Para estimar a idade de uma pessoa, a perícia pode usar, entre outros:","opcoes":["Exame dos ossos e dos dentes","A cor dos olhos","Apenas a altura e o peso da pessoa","O tipo sanguíneo"],"explicacao":"Raio X de mão e punho e arcada dentária."},{"id":3055,"materia":"ml","nivel":2,"enunciado":"A identificação por DNA compara:","opcoes":["Perfis genéticos de amostras biológicas","Impressões digitais colhidas no local do crime","Arcadas dentárias","Fotografias"],"explicacao":"É muito usada em vestígios de crimes."},{"id":3056,"materia":"ml","nivel":2,"enunciado":"A odontologia legal é especialmente útil para identificar:","opcoes":["Corpos carbonizados ou em decomposição","Assinaturas falsas em documentos públicos","Pessoas pela voz","Documentos adulterados"],"explicacao":"Os dentes resistem ao fogo e ao tempo."},{"id":3057,"materia":"ml","nivel":1,"enunciado":"A toxicologia forense estuda:","opcoes":["Venenos e drogas no organismo","Fraturas","Ferimentos por arma branca e suas trajetórias","Asfixias"],"explicacao":"Inclui exames de álcool e entorpecentes."},{"id":3058,"materia":"ml","nivel":2,"enunciado":"A embriaguez é comprovada pericialmente por:","opcoes":["Exame clínico e dosagem de álcool","Apenas fotografia","Apenas o depoimento de testemunhas do fato","Raio X"],"explicacao":"O exame clínico avalia sinais e comportamento."},{"id":3059,"materia":"ml","nivel":2,"enunciado":"A perícia psiquiátrica no processo penal serve para avaliar:","opcoes":["A imputabilidade do acusado","O tipo sanguíneo","A causa da morte da vítima","A altura do réu"],"explicacao":"Pode ser feita no incidente de insanidade mental."},{"id":3060,"materia":"ml","nivel":1,"enunciado":"O atestado médico é um documento que:","opcoes":["Afirma um fato médico e suas consequências","Julga o réu","Manda prender","Substitui sempre a necropsia em mortes violentas"],"explicacao":"Falsificá-lo pode ser crime."},{"id":3061,"materia":"ml","nivel":2,"enunciado":"A declaração de óbito é preenchida, em regra, pelo:","opcoes":["Médico","Delegado","Juiz","Familiar"],"explicacao":"Em mortes violentas, pelo médico-legista."},{"id":3062,"materia":"ml","nivel":2,"enunciado":"Nas mortes violentas ou suspeitas, a necropsia é feita pelo:","opcoes":["Instituto Médico-Legal","Hospital particular mais próximo do local","Cartório","Delegado"],"explicacao":"O IML é o órgão pericial oficial."},{"id":3063,"materia":"ml","nivel":2,"enunciado":"Morte súbita é a que ocorre:","opcoes":["De forma inesperada em pessoa aparentemente saudável","Sempre por violência ou causa externa","Só em idosos doentes","Apenas por envenenamento"],"explicacao":"Pode ser natural, mas exige investigação se suspeita."},{"id":3064,"materia":"ml","nivel":2,"enunciado":"No aborto provocado, a perícia procura, entre outros:","opcoes":["Sinais de manobras abortivas e restos ovulares","A altura da mãe","O tipo sanguíneo do pai e da mãe","Digitais do feto"],"explicacao":"Também lesões no útero."},{"id":3065,"materia":"igual","nivel":2,"enunciado":"Após 2023, a pena do racismo aumenta de 1/3 até a metade quando praticado:","opcoes":["Por funcionário público no exercício da função","À noite","Por pessoa idosa contra pessoa mais jovem","Em feriado"],"explicacao":"Art. 20-B da Lei 7.716/1989."},{"id":3066,"materia":"igual","nivel":2,"enunciado":"O chamado racismo recreativo é o praticado em contexto de:","opcoes":["Descontração, diversão ou recreação","Guerra","Eleições","Atividade bancária ou financeira"],"explicacao":"Art. 20-A da Lei 7.716/1989."},{"id":3067,"materia":"igual","nivel":1,"enunciado":"Pela Lei 7.716/1989, negar emprego em empresa privada por motivo de raça é:","opcoes":["Crime","Só infração trabalhista","Fato atípico","Contravenção"],"explicacao":"Art. 4º da Lei 7.716/1989."},{"id":3068,"materia":"igual","nivel":2,"enunciado":"Pelo Estatuto da Igualdade Racial, a saúde da população negra deve ser garantida pelo:","opcoes":["SUS, com políticas universais e específicas","Apenas planos privados","Somente ONGs","Exclusivamente pelos municípios, sem participação federal"],"explicacao":"Arts. 6º a 8º da Lei 12.288/2010."},{"id":3069,"materia":"igual","nivel":2,"enunciado":"O Estatuto da Igualdade Racial reconhece a capoeira como:","opcoes":["Desporto de criação nacional","Atividade proibida em escolas","Contravenção","Crime"],"explicacao":"Art. 20 da Lei 12.288/2010."},{"id":3070,"materia":"igual","nivel":2,"enunciado":"As comunidades remanescentes de quilombos têm direito:","opcoes":["À propriedade definitiva das terras que ocupam","Apenas ao uso temporário, mediante autorização anual","A nenhuma terra","Só a indenização"],"explicacao":"Art. 68 do ADCT."},{"id":3071,"materia":"igual","nivel":1,"enunciado":"O Dia Nacional de Zumbi e da Consciência Negra é em:","opcoes":["20 de novembro","13 de maio","21 de março","7 de setembro"],"explicacao":"Feriado nacional desde a Lei 14.759/2023."},{"id":3072,"materia":"igual","nivel":2,"enunciado":"O Dia Internacional pela Eliminação da Discriminação Racial é em:","opcoes":["21 de março","20 de novembro","10 de dezembro","8 de março"],"explicacao":"Lembra o Massacre de Sharpeville, de 1960."},{"id":3073,"materia":"igual","nivel":2,"enunciado":"Pela Lei de Tortura, a pena aumenta de 1/6 a 1/3 se a vítima for:","opcoes":["Criança, gestante, idoso, pessoa com deficiência ou adolescente","Homem adulto em plena saúde","Estrangeiro","Servidor público"],"explicacao":"Art. 1º, § 4º, II, da Lei 9.455/1997."},{"id":3074,"materia":"igual","nivel":2,"enunciado":"Hoje, a injúria racial é crime de ação penal:","opcoes":["Pública incondicionada","Privada","Pública condicionada à representação da vítima","Popular"],"explicacao":"Por ter sido equiparada ao racismo."},{"id":3075,"materia":"igual","nivel":2,"enunciado":"Na Lei 2.889/1956, a associação de mais de 3 pessoas para praticar genocídio é:","opcoes":["Crime","Fato atípico","Contravenção","Só infração administrativa"],"explicacao":"Art. 2º da Lei 2.889/1956."},{"id":3076,"materia":"igual","nivel":2,"enunciado":"Na Lei de Genocídio, incitar publicamente a prática de genocídio é:","opcoes":["Crime","Mera opinião permitida","Contravenção","Fato atípico"],"explicacao":"Art. 3º da Lei 2.889/1956."},{"id":3077,"materia":"pen","nivel":1,"enunciado":"Falsificar documento público é crime contra a:","opcoes":["Fé pública","Administração pública","Paz pública","Pessoa"],"explicacao":"Título X do Código Penal."},{"id":3078,"materia":"pen","nivel":2,"enunciado":"A associação criminosa do art. 288 do Código Penal é crime contra a:","opcoes":["Paz pública","Fé pública","Incolumidade pública","Pessoa"],"explicacao":"Exige 3 ou mais pessoas."},{"id":3079,"materia":"pen","nivel":2,"enunciado":"Incêndio e explosão estão entre os crimes contra a:","opcoes":["Incolumidade pública","Fé pública","Paz pública","Administração pública"],"explicacao":"Título VIII do Código Penal."},{"id":3080,"materia":"pen","nivel":2,"enunciado":"A Lei 14.197/2021 incluiu no Código Penal os crimes contra o:","opcoes":["Estado Democrático de Direito","Sistema financeiro e o mercado de capitais","Meio ambiente","Consumidor"],"explicacao":"Substituiu a Lei de Segurança Nacional."},{"id":3081,"materia":"pen","nivel":2,"enunciado":"Tentar depor, com violência ou grave ameaça, o governo legitimamente constituído é crime de:","opcoes":["Golpe de Estado","Sedição","Rixa","Associação criminosa"],"explicacao":"Art. 359-M do Código Penal."},{"id":3082,"materia":"pen","nivel":2,"enunciado":"O assédio sexual exige que o agente se aproveite da condição de:","opcoes":["Superior hierárquico ou ascendência no emprego","Vizinho","Parente distante sem vínculo de trabalho","Desconhecido"],"explicacao":"Art. 216-A do Código Penal."},{"id":3083,"materia":"pen","nivel":2,"enunciado":"Fotografar cena de nudez íntima de alguém sem autorização é crime de:","opcoes":["Registro não autorizado da intimidade sexual","Estupro","Injúria","Ameaça"],"explicacao":"Art. 216-B do Código Penal."},{"id":3084,"materia":"pen","nivel":1,"enunciado":"O furto qualificado por rompimento de obstáculo tem pena de:","opcoes":["Reclusão de 2 a 8 anos","Reclusão de 1 a 4 anos","Detenção de 6 meses","Reclusão de 4 a 10 anos"],"explicacao":"Art. 155, § 4º, I, do Código Penal."},{"id":3085,"materia":"ppen","nivel":1,"enunciado":"A ação civil ex delicto busca:","opcoes":["Reparar o dano causado pelo crime","Prender o réu","Anular o inquérito e arquivar a ação penal","Revisar a pena"],"explicacao":"Proposta no juízo cível."},{"id":3086,"materia":"ppen","nivel":2,"enunciado":"A sentença penal condenatória transitada em julgado, no cível, é:","opcoes":["Título executivo judicial","Prova sem valor","Mera recomendação ao juiz cível, sem força executiva","Título extrajudicial"],"explicacao":"Art. 63 do CPP e art. 515, VI, do CPC."},{"id":3087,"materia":"ppen","nivel":2,"enunciado":"O sequestro de bens, medida assecuratória, recai sobre:","opcoes":["Bens adquiridos com o proveito do crime","Qualquer bem de terceiros","Só imóveis herdados pelo acusado antes do crime","Bens públicos"],"explicacao":"Art. 125 do CPP."},{"id":3088,"materia":"ppen","nivel":2,"enunciado":"A hipoteca legal, no processo penal, recai sobre:","opcoes":["Imóveis do acusado, para garantir a reparação do dano","Bens móveis comprados com o dinheiro do crime","Móveis da vítima","Bens públicos"],"explicacao":"Art. 134 do CPP."},{"id":3089,"materia":"ppen","nivel":2,"enunciado":"São exceções no processo penal, entre outras:","opcoes":["Suspeição, incompetência, litispendência e coisa julgada","Só a prescrição","Revelia","Confissão"],"explicacao":"Art. 95 do CPP."},{"id":3090,"materia":"ppen","nivel":2,"enunciado":"Pelo art. 563 do CPP, nenhum ato será declarado nulo se:","opcoes":["Não houver prejuízo para a acusação ou para a defesa","O juiz quiser preservar o processo por economia","O réu pedir","Faltar o promotor"],"explicacao":"Princípio do prejuízo."},{"id":3091,"materia":"ppen","nivel":1,"enunciado":"O controle externo da atividade policial é exercido pelo:","opcoes":["Ministério Público","Juiz","Delegado-geral da Polícia Civil do estado","Prefeito"],"explicacao":"Art. 129, VII, da CF."},{"id":3092,"materia":"ppen","nivel":2,"enunciado":"As coisas apreendidas não podem ser restituídas enquanto:","opcoes":["Interessarem ao processo","O réu estiver solto","A vítima não pedir","O delegado estiver de férias"],"explicacao":"Art. 118 do CPP."},{"id":3093,"materia":"leg","nivel":2,"enunciado":"Pelo CTB, o condutor que presta pronto e integral socorro à vítima:","opcoes":["Não é preso em flagrante nem paga fiança","É sempre preso","Paga fiança em dobro, fixada pelo delegado","Perde a CNH na hora"],"explicacao":"Art. 301 do CTB."},{"id":3094,"materia":"leg","nivel":1,"enunciado":"Pela Lei de Crimes Ambientais, matar animal silvestre sem autorização é:","opcoes":["Crime","Permitido","Infração de trânsito","Contravenção"],"explicacao":"Art. 29 da Lei 9.605/1998."},{"id":3095,"materia":"leg","nivel":2,"enunciado":"Maus-tratos a cão ou gato têm pena de:","opcoes":["Reclusão de 2 a 5 anos, multa e proibição da guarda","Detenção de 3 meses a 1 ano, sem multa","Só multa","Advertência"],"explicacao":"Art. 32, § 1º-A, da Lei 9.605/1998."},{"id":3096,"materia":"leg","nivel":2,"enunciado":"Pelo ECA, armazenar foto ou vídeo de sexo envolvendo criança ou adolescente é:","opcoes":["Crime","Infração administrativa","Fato atípico","Contravenção"],"explicacao":"Art. 241-B do ECA."},{"id":3097,"materia":"leg","nivel":2,"enunciado":"Pelo Estatuto da Pessoa Idosa, deixar de prestar assistência ao idoso, quando possível fazê-lo sem risco, é:","opcoes":["Crime","Fato atípico","Infração de trânsito","Contravenção"],"explicacao":"Art. 97 da Lei 10.741/2003."},{"id":3098,"materia":"leg","nivel":2,"enunciado":"Pelo Estatuto da Pessoa com Deficiência, discriminar alguém em razão da deficiência é:","opcoes":["Crime, punido com reclusão de 1 a 3 anos e multa","Só infração civil, com indenização à vítima","Contravenção","Fato atípico"],"explicacao":"Art. 88 da Lei 13.146/2015."},{"id":3099,"materia":"leg","nivel":2,"enunciado":"Após a Lei Henry Borel, o homicídio contra menor de 14 anos é:","opcoes":["Qualificado e hediondo","Simples","Culposo","Privilegiado"],"explicacao":"Art. 121, § 2º, IX, do Código Penal."},{"id":3100,"materia":"leg","nivel":2,"enunciado":"Pela Lei de Prisão Temporária, o preso temporário deve ficar:","opcoes":["Separado dos demais detentos","Junto com os condenados, em regime fechado","Em casa","Em hospital"],"explicacao":"Art. 3º da Lei 7.960/1989."},{"id":3101,"materia":"leg","nivel":1,"enunciado":"Pela Lei 9.296/1996, a interceptação pode ser requerida pela autoridade policial ou pelo:","opcoes":["Ministério Público","Advogado da vítima","Prefeito","Jornalista"],"explicacao":"Também pode ser determinada de ofício pelo juiz."},{"id":3102,"materia":"leg","nivel":2,"enunciado":"Pelo Código Eleitoral, comprar votos (art. 299) é:","opcoes":["Crime eleitoral","Infração administrativa","Permitido","Contravenção"],"explicacao":"Corrupção eleitoral."},{"id":3103,"materia":"leg","nivel":1,"enunciado":"A Declaração Universal dos Direitos Humanos foi adotada pela Resolução:","opcoes":["217-A (III) da Assembleia Geral da ONU","1 do Conselho de Segurança","45 da OEA","100 da Organização Internacional do Trabalho"],"explicacao":"Em 10 de dezembro de 1948."},{"id":3104,"materia":"const","nivel":1,"enunciado":"A Polícia Rodoviária Federal faz o patrulhamento ostensivo das:","opcoes":["Rodovias federais","Ferrovias","Fronteiras marítimas","Ruas dos municípios"],"explicacao":"Art. 144, § 2º, da CF."},{"id":3105,"materia":"const","nivel":1,"enunciado":"As polícias penais cuidam da:","opcoes":["Segurança dos estabelecimentos penais","Investigação de crimes","Fiscalização do trânsito nas rodovias estaduais","Defesa das fronteiras"],"explicacao":"Incluídas pela EC 104/2019."},{"id":3106,"materia":"const","nivel":2,"enunciado":"Para o STF, as guardas municipais integram o:","opcoes":["Sistema de segurança pública","Poder Judiciário","Ministério Público","Exército"],"explicacao":"ADPF 995, de 2023."},{"id":3107,"materia":"const","nivel":1,"enunciado":"Os direitos políticos são suspensos, entre outros casos, por:","opcoes":["Condenação criminal transitada em julgado, enquanto durarem os efeitos","Mudança de cidade sem transferência do título","Desemprego","Divórcio"],"explicacao":"Art. 15, III, da CF."},{"id":3108,"materia":"adm","nivel":2,"enunciado":"O Estado que indeniza a vítima pode cobrar do agente público por:","opcoes":["Ação regressiva, se houver dolo ou culpa","Desconto automático no salário, sem processo","Prisão do agente","Nada, nunca"],"explicacao":"Art. 37, § 6º, da CF."},{"id":3109,"materia":"adm","nivel":1,"enunciado":"O abuso de poder se divide em:","opcoes":["Excesso de poder e desvio de finalidade","Uso e desuso","Ilegalidade, imoralidade e ineficiência","Dolo e culpa"],"explicacao":"Excesso: fora da competência; desvio: fim diverso."},{"id":3110,"materia":"adm","nivel":2,"enunciado":"O poder regulamentar permite ao chefe do Executivo:","opcoes":["Editar decretos para a fiel execução das leis","Criar crimes","Criar tributos","Julgar recursos judiciais contra a Administração"],"explicacao":"Art. 84, IV, da CF."},{"id":3111,"materia":"adm","nivel":1,"enunciado":"O emprego público é regido, em regra, pela:","opcoes":["CLT","Lei 8.112/1990","Constituição estadual","Lei Orgânica da Polícia"],"explicacao":"O cargo público tem regime estatutário."},{"id":3112,"materia":"port","nivel":2,"enunciado":"Em “Se chover, não sairei”, o “se” é:","opcoes":["Conjunção condicional","Pronome apassivador","Índice de indeterminação do sujeito","Pronome reflexivo"],"explicacao":"Introduz uma condição."},{"id":3113,"materia":"port","nivel":1,"enunciado":"Pelo Manual de Redação da Presidência, o fecho para autoridade de hierarquia superior é:","opcoes":["Respeitosamente","Atenciosamente","Abraços","Cordialmente"],"explicacao":"“Atenciosamente” é para mesma hierarquia ou inferior."},{"id":3114,"materia":"port","nivel":2,"enunciado":"Pelo Manual de Redação da Presidência, o vocativo para o Presidente da República é:","opcoes":["Excelentíssimo Senhor Presidente da República","Ilustríssimo Senhor Presidente","Prezado Senhor Presidente da República Federativa","Caro Senhor Presidente"],"explicacao":"Para os chefes de Poder."},{"id":3115,"materia":"port","nivel":2,"enunciado":"Na 3ª edição do Manual de Redação da Presidência, ofício, aviso e memorando foram unificados no:","opcoes":["Padrão Ofício","Padrão Memorando","Padrão Carta","Padrão Ata"],"explicacao":"Muda apenas o nome do expediente."},{"id":3116,"materia":"port","nivel":1,"enunciado":"O pronome de tratamento usado para juízes é:","opcoes":["Vossa Excelência","Vossa Senhoria","Vossa Magnificência","Vossa Santidade"],"explicacao":"Magnificência é para reitores."},{"id":3117,"materia":"rl","nivel":2,"enunciado":"Num grupo, 30 gostam de café, 20 de chá e 10 de ambos. Quantos gostam de pelo menos um?","opcoes":["40","50","60","30"],"explicacao":"30 + 20 − 10 = 40."},{"id":3118,"materia":"rl","nivel":2,"enunciado":"A solução do sistema x + y = 10 e x − y = 2 é:","opcoes":["x = 6 e y = 4","x = 5 e y = 5","x = 7 e y = 3","x = 4 e y = 6"],"explicacao":"Somando: 2x = 12."},{"id":3119,"materia":"rl","nivel":2,"enunciado":"As raízes de x² − 5x + 6 = 0 são:","opcoes":["2 e 3","1 e 6","−2 e −3","5 e 6"],"explicacao":"Soma 5 e produto 6."},{"id":3120,"materia":"rl","nivel":1,"enunciado":"Quanto é 3/8 de 64?","opcoes":["24","18","32","21"],"explicacao":"64 ÷ 8 × 3."},{"id":3121,"materia":"rl","nivel":2,"enunciado":"Dividindo R$ 900 em partes proporcionais a 2 e 7, a maior parte é:","opcoes":["R$ 700","R$ 600","R$ 450","R$ 200"],"explicacao":"900 ÷ 9 = 100; 7 × 100."},{"id":3122,"materia":"inf","nivel":1,"enunciado":"No PowerPoint, Ctrl + M serve para:","opcoes":["Inserir um novo slide","Salvar","Imprimir","Fechar"],"explicacao":"Atalho clássico do PowerPoint."},{"id":3123,"materia":"inf","nivel":2,"enunciado":"No Windows 11, o atalho Windows + Shift + S abre:","opcoes":["A ferramenta de captura de tela","O menu Iniciar","O Gerenciador de Tarefas do Windows","As Configurações"],"explicacao":"Permite recortar parte da tela."},{"id":3124,"materia":"inf","nivel":2,"enunciado":"No Excel, =DIAS(\"10/01/2026\";\"01/01/2026\") retorna:","opcoes":["9","10","−9","1"],"explicacao":"DIAS(data final; data inicial)."},{"id":3125,"materia":"inf","nivel":2,"enunciado":"No Word, o recurso Controlar Alterações serve para:","opcoes":["Registrar as mudanças feitas no documento","Corrigir automaticamente a ortografia","Criar índice","Contar palavras"],"explicacao":"Fica na guia Revisão."},{"id":3126,"materia":"cont","nivel":2,"enunciado":"O desconto comercial simples é calculado sobre o:","opcoes":["Valor nominal do título","Valor atual","Valor futuro com juros compostos","Lucro"],"explicacao":"Também chamado de desconto “por fora”."},{"id":3127,"materia":"cont","nivel":2,"enunciado":"Na folha de pagamento, o FGTS é encargo:","opcoes":["Do empregador","Descontado do empregado","Do governo","Opcional"],"explicacao":"8% sobre a remuneração, em regra."},{"id":3128,"materia":"cont","nivel":1,"enunciado":"Uma taxa de 12% ao ano equivale, proporcionalmente, a:","opcoes":["1% ao mês","12% ao mês","0,5% ao mês","2% ao mês"],"explicacao":"Taxas proporcionais: 12 ÷ 12."},{"id":3129,"materia":"est","nivel":2,"enunciado":"Na amostragem estratificada proporcional, cada estrato entra na amostra:","opcoes":["Com peso proporcional ao seu tamanho na população","Com o mesmo número de elementos, qualquer que seja o tamanho","Com apenas 1 elemento","Só se for grande"],"explicacao":"Garante representatividade dos grupos."},{"id":3130,"materia":"est","nivel":2,"enunciado":"Dois eventos são independentes quando:","opcoes":["P(A e B) = P(A) × P(B)","P(A) + P(B) = 1","Não podem ocorrer juntos","P(A) = P(B)"],"explicacao":"Um não altera a chance do outro."},{"id":3131,"materia":"ml","nivel":2,"enunciado":"Na necropsia completa, abrem-se as três cavidades:","opcoes":["Craniana, torácica e abdominal","Bucal, nasal e auditiva","Pélvica, bucal e nasal","Das mãos, dos pés e das costas"],"explicacao":"Exame interno padrão do cadáver."},{"id":3132,"materia":"ml","nivel":2,"enunciado":"Lesão corporal que causa debilidade permanente de membro é classificada como:","opcoes":["Grave","Gravíssima","Leve","Culposa"],"explicacao":"Art. 129, § 1º, III, do Código Penal."},{"id":3133,"materia":"ml","nivel":2,"enunciado":"A deformidade permanente torna a lesão corporal:","opcoes":["Gravíssima","Grave","Leve","Simples"],"explicacao":"Art. 129, § 2º, IV, do Código Penal."},{"id":3134,"materia":"ml","nivel":2,"enunciado":"Se a lesão corporal acelera o parto, ela é classificada como:","opcoes":["Grave","Gravíssima","Leve","Atípica"],"explicacao":"Art. 129, § 1º, IV, do Código Penal."},{"id":3135,"materia":"ml","nivel":2,"enunciado":"Se a lesão corporal provoca aborto, ela é classificada como:","opcoes":["Gravíssima","Grave","Leve","Culposa"],"explicacao":"Art. 129, § 2º, V, do Código Penal."},{"id":3136,"materia":"adm","nivel":2,"enunciado":"Em regra, a autoexecutoriedade NÃO alcança a cobrança de:","opcoes":["Multas, que dependem de execução judicial","Demolição de obra em risco iminente","Apreensão de alimentos estragados","Interdição de estabelecimento perigoso à saúde pública"],"explicacao":"A Administração aplica a multa, mas cobra na Justiça."},{"id":3137,"materia":"ml","nivel":2,"enunciado":"Em regra, a necropsia só deve ser feita depois de pelo menos:","opcoes":["6 horas do óbito","1 hora do óbito","24 horas do óbito","48 horas do óbito"],"explicacao":"Art. 162 do CPP, salvo sinais evidentes de morte."},{"id":3138,"materia":"ml","nivel":2,"enunciado":"A incapacidade permanente para o trabalho torna a lesão corporal:","opcoes":["Gravíssima","Grave","Leve","Culposa"],"explicacao":"Art. 129, § 2º, I, do Código Penal."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('ml','igual') group by materia;
select count(*) as total_de_questoes from public.questoes;
